exercise.solution:
trait Describe {
    fn name(&self) -> String;
    fn size(&self) -> u32;

    fn summary(&self) -> String {
        format!("{} of size {}", self.name(), self.size())
    }
}

struct Crate {
    side: u32,
}

struct Barrel {
    label: &'static str,
    liters: u32,
}

impl Describe for Crate {
    fn name(&self) -> String {
        String::from("crate")
    }

    fn size(&self) -> u32 {
        self.side * self.side * self.side
    }
}

impl Describe for Barrel {
    fn name(&self) -> String {
        format!("barrel {}", self.label)
    }

    fn size(&self) -> u32 {
        self.liters
    }

    fn summary(&self) -> String {
        format!("{} holding {} liters", self.name(), self.liters)
    }
}

struct Inventory<T> {
    items: Vec<T>,
}

impl<T: Describe> Inventory<T> {
    fn new() -> Inventory<T> {
        Inventory { items: Vec::new() }
    }

    fn add(&mut self, item: T) {
        self.items.push(item);
    }

    fn total_size(&self) -> u32 {
        let mut total = 0;
        for item in &self.items {
            total += item.size();
        }
        total
    }
}

fn bigger<'a, T: Describe>(a: &'a T, b: &'a T) -> &'a T {
    if b.size() > a.size() { b } else { a }
}

fn main() {
    let wine = Barrel { label: "wine", liters: 50 };
    let oil = Barrel { label: "oil", liters: 50 };
    let water = Barrel { label: "water", liters: 80 };
    println!("{}", wine.summary());
    println!("{}", bigger(&wine, &oil).name());
    println!("{}", bigger(&oil, &water).name());

    let mut crates: Inventory<Crate> = Inventory::new();
    println!("total: {}", crates.total_size());
    crates.add(Crate { side: 2 });
    crates.add(Crate { side: 3 });
    println!("total: {}", crates.total_size());
    println!("{}", bigger(&crates.items[0], &crates.items[1]).summary());
}
